def to_base(x, b):
    if x == 0:
        return "0"
    digits = "0123456789abcdef"
    out = []
    while x:
        out.append(digits[x % b])
        x //= b
    return "".join(reversed(out))
assert to_base(255, 16) == "ff" and to_base(5, 2) == "101" and to_base(0, 7) == "0"
