def merge(intervals):
    intervals.sort()
    res = []
    for s, e in intervals:
        if res and s <= res[-1][1]:
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res
assert merge([[1, 3], [2, 6], [8, 10], [9, 9]]) == [[1, 6], [8, 10]]

def subarray_sum(nums, k):
    cnt = {0: 1}
    pre = ans = 0
    for x in nums:
        pre += x
        ans += cnt.get(pre - k, 0)    # 先查
        cnt[pre] = cnt.get(pre, 0) + 1   # 后加
    return ans
assert subarray_sum([1, 1, 1], 2) == 2 and subarray_sum([1, -1, 0], 0) == 3

def next_greater_distance(a):
    res = [0] * len(a)
    st = []                      # 存下标，对应值单调递减
    for i, x in enumerate(a):
        while st and a[st[-1]] < x:
            j = st.pop()
            res[j] = i - j
        st.append(i)
    return res
assert next_greater_distance([730, 740, 750, 710, 690, 720, 760, 730]) == [1, 1, 4, 2, 1, 1, 0, 0]

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def build(arr):
    dummy = ListNode()
    cur = dummy
    for v in arr:
        cur.next = ListNode(v)
        cur = cur.next
    return dummy.next

def to_list(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out

def reverse(head):
    prev, cur = None, head
    while cur:
        nxt = cur.next          # 先保存
        cur.next = prev
        prev, cur = cur, nxt
    return prev

assert to_list(reverse(build([1, 2, 3]))) == [3, 2, 1] and to_list(reverse(None)) == []

class N:
    def __init__(self, v, n=None): self.val, self.next = v, n
def middle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow
h = N(1, N(2, N(3, N(4, N(5)))))
assert middle(h).val == 3

def lower_bound(a, target):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo
import bisect
a = [1, 3, 3, 5]
assert lower_bound(a, 3) == 1 == bisect.bisect_left(a, 3) and lower_bound(a, 6) == 4

def min_ok(lo, hi, check):        # 要求 check(hi) 为 True，且 check 单调
    while lo < hi:
        mid = (lo + hi) // 2
        if check(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
assert min_ok(0, 100, lambda x: x * x >= 50) == 8

from collections import deque
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def build_level(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    q = deque([root])
    i = 1
    while q and i < len(arr):
        node = q.popleft()
        if i < len(arr) and arr[i] is not None:
            node.left = TreeNode(arr[i]); q.append(node.left)
        i += 1
        if i < len(arr) and arr[i] is not None:
            node.right = TreeNode(arr[i]); q.append(node.right)
        i += 1
    return root

def preorder(n):
    return [n.val] + preorder(n.left) + preorder(n.right) if n else []
assert preorder(build_level([1, 2, 3, None, 4])) == [1, 2, 4, 3]

def post_from(pre, ino):
    pos = {v: i for i, v in enumerate(ino)}
    it = iter(pre)
    out = []
    def rec(l, r):
        if l > r:
            return
        v = next(it)
        m = pos[v]
        rec(l, m - 1)       # 左子树
        rec(m + 1, r)       # 右子树
        out.append(v)       # 后序：最后放根
    rec(0, len(ino) - 1)
    return "".join(out)
assert post_from("ABDEC", "DBEAC") == "DEBCA"

def permute_unique(nums):
    nums.sort()
    res, path = [], []
    used = [False] * len(nums)
    def dfs():
        if len(path) == len(nums):
            res.append(path[:])
            return
        for i in range(len(nums)):
            if used[i]:
                continue
            if i > 0 and nums[i] == nums[i - 1] and not used[i - 1]:
                continue                  # 同一层跳过重复值
            used[i] = True; path.append(nums[i])
            dfs()
            path.pop(); used[i] = False   # 撤销选择
    dfs()
    return res
assert len(permute_unique([1, 1, 2])) == 3

from functools import lru_cache
def count_paths(grid, sr, sc, er, ec):
    n, m = len(grid), len(grid[0])
    @lru_cache(None)
    def f(r, c):
        if (r, c) == (er, ec):
            return 1
        total = 0
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] > grid[r][c]:
                total += f(nr, nc)
        return total
    return f(sr, sc)
assert count_paths([[1, 2], [3, 5]], 0, 0, 1, 1) == 2

parent = list(range(5))
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]   # 路径压缩
        x = parent[x]
    return x
def union(a, b):
    parent[find(a)] = find(b)
union(0, 1); union(3, 4)
assert find(0) == find(1) and find(0) != find(3) and len({find(i) for i in range(5)}) == 3

from collections import defaultdict, deque
def is_bipartite(n, edges):            # 节点编号 1..n
    g = defaultdict(list)
    for a, b in edges:
        g[a].append(b); g[b].append(a)
    color = {}
    for s in range(1, n + 1):
        if s in color:
            continue
        color[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in g[u]:
                if v not in color:
                    color[v] = 1 - color[u]; q.append(v)
                elif color[v] == color[u]:
                    return False
    return True
assert is_bipartite(4, [(1, 2), (2, 3), (3, 4), (4, 1)]) and not is_bipartite(3, [(1, 2), (2, 3), (1, 3)]) and not is_bipartite(1, [(1, 1)])

def max_non_overlap(intervals):
    intervals.sort(key=lambda x: x[1])
    cnt, end = 0, float("-inf")
    for s, e in intervals:
        if s >= end:
            cnt += 1
            end = e
    return cnt
assert max_non_overlap([[1, 5], [2, 3], [4, 6]]) == 2 and max_non_overlap([[1, 2], [2, 3]]) == 2

def lcs(a, b):
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[n][m]
assert lcs("abcde", "ace") == 3
